vec2 boxHitT(vec3 ro,vec3 rd,vec3 b,out vec3 n){
  vec3 m=1./rd;vec3 nn=m*ro;vec3 k=abs(m)*b;vec3 t1=-nn-k,t2=-nn+k;
  float tN=max(max(t1.x,t1.y),t1.z);float tF=min(min(t2.x,t2.y),t2.z);
  n=vec3(0.);if(tN>tF||tF<0.)return vec2(-1.);
