  vec3 hb=vec3(A.x*.5,.5,A.x*.5);
  float D=hb.z+2.2+sin(pr*PI)*mix(0.,2.5,uP2);
  float f=2.2;
  vec3 ro=vec3(0.,0.,D);vec3 rd=normalize(vec3(p,-f));
