  mat3 Ry=mat3(c,0.,-s,0.,1.,0.,s,0.,c);
  vec3 lro=Ry*ro,lrd=Ry*rd;vec3 n;
  vec2 t=boxHitT(lro,lrd,hb,n);
  vec3 col=(TAl(uv,5.).rgb*(1.-pr)+TBl(uv,5.).rgb*pr)*uP5;
  if(t.x>0.){
