    vec3 fc;float shade;
    if(n.z>.5){fc=TA(vec2(h.x/A.x+.5,h.y+.5)).rgb;shade=abs(c);}
    else if(n.x*sgn>.5){fc=TB(vec2(-h.z*sgn/A.x+.5,h.y+.5)).rgb;shade=abs(s);}
    else{fc=vec3(.02);shade=.5;}
    vec3 a=abs(h)/hb;float mid=a.x+a.y+a.z-max(a.x,max(a.y,a.z))-min(a.x,min(a.y,a.z));
    col=fc*(.35+.65*shade)+vec3(1.)*exp(-(1.-mid)*hb.y/.006)*uP4*sin(pr*PI);
  }
  return col;
}

