float chromeH(vec2 p,vec2 b,float w,float t,out float ww,out float edge){
  edge=-sdRB(p,b,0.);
  float wob=(fbm(p*2.2+vec2(t,-t*.7))-.5)*w*.8;
  ww=w+wob;
  float x=clamp(edge/ww,0.,1.);
  float h=sin(PI*x);
  h+=(fbm(p*mix(3.,9.,uP5)+vec2(-t*1.3,t))-.5)*.14;
  h+=kick()*uP3*.18*sin(edge*60.-uTime*10.)*(1.-x);
  return h*smoothstep(ww,ww-.003,edge);
}
