vec3 fx(vec2 uv){
  vec2 A=aspect();vec2 p=(uv-.5)*A;
  float tilt=mix(0.,.9,uP3);
  float zf=1./max(1.+p.y*tilt*.8,.2);
  vec2 q=vec2(p.x*zf,p.y*zf*(1.+tilt*.3));
  float nl=floor(mix(40.,160.,uP0));float sp=1./nl;
  float amp=mix(.02,.25,uP1)*(1.+.3*kick());
  float px=1.2/uRes.y*zf;
  float thick=px*mix(.6,2.5,uP2);
  vec3 col=vec3(0.);
  float base=floor((q.y+.5)/sp);
  float K=min(amp/sp+2.,40.);
  for(int i=-1;i<42;i++){
    if(float(i)>K)break;
    float li=base-float(i);
    float y0=li*sp-.5;
    vec2 suv=vec2(q.x/A.x+.5,y0+.5);
    if(suv.y<0.||suv.y>1.||suv.x<0.||suv.x>1.)continue;
    vec3 c=textureLod(uSrc,suv,1.).rgb;float l=luma(c);
    float d=abs(q.y-(y0+l*amp));
    float ln=smoothstep(thick,0.,d)+exp(-d/(thick*4.))*uP5*.6;
    vec3 lc=mix(c*1.6+.04,hsv(.5+uTime*.02+l*.3,.6,1.)*(.3+l),uP4);
    col=max(col,lc*ln*(.3+l));
  }
  return col;
}

vec3 fx(vec2 uv){
