vec3 fx(vec2 uv){
  float div=exp2(floor(uP0*2.99)+1.);
  float ph=fract(uBeats*div);
  float gap=max(uFPB/div,1.);
  vec3 s=src(uv).rgb;vec3 col=s;
  float n=floor(mix(2.,6.,uP1));
  vec2 drift=vec2(1.,.35)*mix(0.,.012,uP2);
  for(int j=0;j<6;j++){
    float fj=float(j);if(fj>=n)break;
    float age=(ph+fj+1.)*gap;if(age>46.)break;
    vec3 h=hist(uv-drift*(fj+1.),age);
    float w=pow(mix(.4,.88,uP3),fj+1.);
    vec3 tint=mix(vec3(1.),hsv(uP4+fj*.12,.8,1.),uP5);
    col=max(col,h*tint*w*smoothstep(.12,.3,luma(h)));
  }
  return col;
}

vec2 curl(vec2 p){float e=.02;float a=fbm(p+vec2(0.,e)),b=fbm(p-vec2(0.,e)),c=fbm(p+vec2(e,0.)),d=fbm(p-vec2(e,0.));return vec2(a-b,-(c-d))/(2.*e);}
