  float shuffle=floor(uBeats*rate);float ph=fract(uBeats*rate);
  float base=floor(mix(3.,10.,uP0));
  vec2 g=vec2(floor(base*A.x),base);
  vec2 c=floor(uv*g);
  float depth=floor(uP3*3.99);
  for(int i=0;i<3;i++){if(float(i)>=depth)break;if(h21(c+shuffle*.37+float(i)*9.1)>.5){g*=2.;c=floor(uv*g);}}
  vec2 f=fract(uv*g);
